 {"id": "PEDS-C28-041", "sec": "Epiglottitis — clinical", "page": 124, "q": "Stridor in epiglottitis is due to inflammation of the ___ area.", "opts": ["Alveolar", "Supraglottic", "Subglottic", "Bronchiolar"], "ans": 1, "exp": "Stridor d/t inflammation of supraglottic area (Book p124)", "type": "mcq"},
 {"id": "PEDS-C28-042", "sec": "Epiglottitis — clinical", "page": 124, "q": "The 3 D's of epiglottitis are dysphagia, drooling of saliva and ___.", "opts": ["diplopia", "dysuria", "dyspnea / respiratory distress", "diarrhea"], "ans": 2, "exp": "3 D's: dysphagia, drooling of saliva, dyspnea/respiratory distress (Book p124)", "type": "fill"},
 {"id": "PEDS-C28-043", "sec": "Epiglottitis — clinical", "page": 124, "q": "Odd one out (the 3 D's):", "opts": ["Dysphagia", "Drooling of saliva", "Dyspnea", "Diarrhea"], "ans": 3, "exp": "The 3 D's are dysphagia, drooling, dyspnea; diarrhea is not one. (Book p124)", "type": "odd"},
 {"id": "PEDS-C28-044", "sec": "Epiglottitis — clinical", "page": 124, "q": "Tripod posture (leaning forward) in epiglottitis helps open up the airway.", "opts": ["True", "False"], "ans": 0, "exp": "True — tripod posture: leaning forward opens up the airway (Book p124)", "type": "tf"},
 {"id": "PEDS-C28-045", "sec": "Epiglottitis — clinical", "page": 124, "q": "High-grade fever in a child with airway obstruction favours a viral etiology.", "opts": ["True", "False"], "ans": 1, "exp": "False — bacterial (epiglottitis) gives high-grade fever; low-grade fever is seen in viral infections (Book p124)", "type": "tf"},
 {"id": "PEDS-C28-046", "sec": "Epiglottitis — clinical", "page": 124, "stem": "A 4-year-old presents sick-looking with high-grade fever, drooling, dysphagia and stridor.", "q": "The most likely diagnosis is —", "opts": ["Acute bronchiolitis", "Atypical pneumonia", "Acute epiglottitis", "Mild croup"], "ans": 2, "exp": "Sick child + high fever + 3 D's + stridor = acute epiglottitis. (Book p124)", "type": "case"},
 {"id": "PEDS-C28-047", "sec": "Epiglottitis — investigations", "page": 124, "q": "The X-ray sign of a swollen epiglottis is the ___ sign.", "opts": ["steeple", "sail", "hammer", "thumb"], "ans": 3, "exp": "Thumb sign: soft tissue shadow of swollen epiglottis (Book p124)", "type": "fill"},
 {"id": "PEDS-C28-048", "sec": "Epiglottitis — investigations", "page": 124, "q": "On laryngoscopy, the epiglottis in acute epiglottitis appears —", "opts": ["Inflamed and cherry-red", "Pale and atrophic", "Ulcerated and white", "Normal"], "ans": 0, "exp": "Inflamed cherry-red epiglottis (Book p124)", "type": "mcq"},
 {"id": "PEDS-C28-049", "sec": "Epiglottitis — investigations", "page": 124, "q": "Laryngoscopy is done routinely in suspected acute epiglottitis.", "opts": ["True", "False"], "ans": 1, "exp": "False — not done routinely (Book p124)", "type": "tf"},
 {"id": "PEDS-C28-050", "sec": "Epiglottitis — investigations", "page": 124, "q": "Laryngoscopy is avoided routinely because stimulation by the scope can cause —", "opts": ["Vagal bradycardia only", "Immediate defervescence", "Laryngospasm predisposing to respiratory arrest", "Hypertensive crisis"], "ans": 2, "exp": "Stimulation by laryngoscope → laryngospasm → predisposes to respiratory arrest (Book p124)", "type": "mcq"},
 {"id": "PEDS-C28-051", "sec": "Epiglottitis — management", "page": 125, "q": "The first priority in managing acute epiglottitis is to secure the ___.", "opts": ["IV line", "antibiotic level", "temperature", "airway"], "ans": 3, "exp": "Secure airway (priority) (Book p125)", "type": "fill"},
 {"id": "PEDS-C28-052", "sec": "Epiglottitis — management", "page": 125, "q": "If intubation is not possible in epiglottitis, the next step is —", "opts": ["Tracheostomy", "Cricoid pressure", "Nebulised epinephrine", "Head-down position"], "ans": 0, "exp": "Intubation → if not possible, tracheostomy (Book p125)", "type": "mcq"},
 {"id": "PEDS-C28-053", "sec": "Epiglottitis — management", "page": 125, "q": "The IV antibiotics used in acute epiglottitis are —", "opts": ["Oral azithromycin", "3rd-generation cephalosporins (ceftriaxone/cefotaxime)", "Oral amoxicillin", "Inhaled ribavirin"], "ans": 1, "exp": "IV antibiotics: 3rd generation cephalosporin — IV ceftriaxone, IV cefotaxime (Book p125)", "type": "mcq"},
 {"id": "PEDS-C28-054", "sec": "Epiglottitis — management", "page": 125, "q": "Odd one out (epiglottitis antibiotics):", "opts": ["IV ceftriaxone", "IV cefotaxime", "IV vancomycin", "3rd-generation cephalosporin"], "ans": 2, "exp": "Ceftriaxone/cefotaxime are 3rd-generation cephalosporins used; vancomycin is not part of the listed regimen. (Book p125)", "type": "odd"},
 {"id": "PEDS-C28-055", "sec": "Epiglottitis — signs", "page": 125, "q": "Match sign with condition — select the correct combination:", "pairs": [["Thumb sign", "croup"], ["Steeple sign", "epiglottitis"], ["Cherry-red epiglottis", "opens airway"], ["Tripod posture", "laryngoscopy"]], "opts": ["A-2, B-4, C-3, D-1", "A-1, B-3, C-4, D-2", "A-4, B-2, C-1, D-3", "A-2, B-1, C-4, D-3"], "ans": 3, "exp": "Correct pairs: Thumb sign→epiglottitis; Steeple sign→croup; Cherry-red epiglottis→laryngoscopy; Tripod posture→opens airway. (Book p125)", "type": "match"},
 {"id": "PEDS-C28-056", "sec": "Epiglottitis — management", "page": 125, "stem": "A child with acute epiglottitis arrives with increasing stridor and drooling.", "q": "The single most important immediate step is —", "opts": ["Securing the airway", "Starting oral dexamethasone", "Ordering a cold agglutination test", "Giving inhaled salbutamol"], "ans": 0, "exp": "Secure airway is the priority; then IV 3rd-gen cephalosporin. (Book p125)", "type": "case"},
 {"id": "PEDS-C28-057", "sec": "Bronchiolitis — incidence", "page": 125, "q": "Acute bronchiolitis incidence increases during ___.", "opts": ["spring", "winter", "summer", "monsoon"], "ans": 1, "exp": "↑ during winter (Book p125)", "type": "fill"},
 {"id": "PEDS-C28-058", "sec": "Bronchiolitis — incidence", "page": 125, "q": "Bronchiolitis affects children < 2 yrs, peaking at ___ months.", "opts": ["12–18", "24–30", "3–6", "9–12"], "ans": 2, "exp": "Age < 2 yrs (peaks 3 to 6 months) (Book p125)", "type": "fill"},
 {"id": "PEDS-C28-059", "sec": "Bronchiolitis — etiology", "page": 125, "q": "The etiology of acute bronchiolitis is —", "opts": ["Parainfluenza type 1", "Hemophilus influenzae b", "Mycoplasma", "Respiratory syncytial virus"], "ans": 3, "exp": "Etiology: Respiratory Syncytial Virus (RSV) (Book p125)", "type": "mcq"},
 {"id": "PEDS-C28-060", "sec": "Bronchiolitis — etiology", "page": 125, "q": "The more severe RSV type is —", "opts": ["Type A", "Type B", "Type 1", "Type 3"], "ans": 0, "exp": "Type A (more severe) (Book p125)", "type": "mcq"},
 {"id": "PEDS-C28-061", "sec": "Bronchiolitis — etiology", "page": 125, "q": "RSV can cause both upper and lower respiratory tract infections.", "opts": ["True", "False"], "ans": 0, "exp": "True — RSV can cause URIs and LRIs (Book p125)", "type": "tf"},
 {"id": "PEDS-C28-062", "sec": "Bronchiolitis — pathogenesis", "page": 125, "q": "Inflammation of bronchioles causes edema and increased ___.", "opts": ["elastic recoil", "ciliary beat", "mucus production", "surfactant"], "ans": 2, "exp": "Inflammation → edema + ↑ mucus production (Book p125)", "type": "fill"},
 {"id": "PEDS-C28-063", "sec": "Bronchiolitis — pathogenesis", "page": 125, "q": "Airway narrowing in bronchiolitis is maximal during —", "opts": ["Inspiration", "Mid-inspiration", "Apnea", "Expiration"], "ans": 3, "exp": "↑↑ narrowing of airway during expiration → air-trapping (Book p125)", "type": "mcq"},
 {"id": "PEDS-C28-064", "sec": "Bronchiolitis — pathogenesis", "page": 125, "q": "The air-trapping of bronchiolitis results from airway narrowing during inspiration.", "opts": ["True", "False"], "ans": 1, "exp": "False — narrowing is during expiration, causing air-trapping (Book p125)", "type": "tf"},
 {"id": "PEDS-C28-065", "sec": "Bronchiolitis — clinical", "page": 125, "q": "Air-trapping in bronchiolitis increases the ___ diameter of the chest.", "opts": ["crown–heel", "AP", "transverse", "vertical"], "ans": 1, "exp": "↑ AP diameter (Book p125)", "type": "fill"},
 {"id": "PEDS-C28-066", "sec": "Bronchiolitis — clinical", "page": 125, "q": "Percussion in bronchiolitis yields ___.", "opts": ["stoniness", "normal resonance", "hyper-resonance", "dullness"], "ans": 2, "exp": "Hyper-resonance on percussion (Book p125)", "type": "fill"},
 {"id": "PEDS-C28-067", "sec": "Bronchiolitis — clinical", "page": 125, "q": "Narrowing of the bronchioles in bronchiolitis produces ___.", "opts": ["stridor", "bronchial breathing", "silent chest only", "wheeze"], "ans": 3, "exp": "Narrowing bronchioles → wheeze (Book p125)", "type": "fill"},
 {"id": "PEDS-C28-068", "sec": "Bronchiolitis — investigations", "page": 125, "q": "Peribronchial cuffing on bronchiolitis X-ray is due to —", "opts": ["Inflammatory exudates", "Air-filled cysts", "Pleural fluid", "Calcified nodes"], "ans": 0, "exp": "Peribronchial cuffing d/t inflammatory exudates (Book p125)", "type": "mcq"},
 {"id": "PEDS-C28-069", "sec": "Bronchiolitis — investigations", "page": 125, "q": "The other characteristic X-ray finding in bronchiolitis is —", "opts": ["Mediastinal shift", "Bilateral hyperinflation", "Lobar consolidation", "Pneumatocele"], "ans": 1, "exp": "Bilateral hyperinflation (Book p125)", "type": "mcq"},
 {"id": "PEDS-C28-070", "sec": "Bronchiolitis — investigations", "page": 125, "q": "RSV is confirmed on a nasopharyngeal swab by ___.", "opts": ["cold agglutination", "Gram stain", "PCR", "culture on blood agar"], "ans": 2, "exp": "Nasopharyngeal swab: PCR for RSV (Book p125)", "type": "fill"},
 {"id": "PEDS-C28-071", "sec": "Bronchiolitis — management", "page": 125, "q": "Acute bronchiolitis is usually self-limiting, lasting 3 to 7 days.", "opts": ["True", "False"], "ans": 0, "exp": "True — usually self-limiting (3 to 7 days) (Book p125)", "type": "tf"},
 {"id": "PEDS-C28-072", "sec": "Bronchiolitis — management", "page": 125, "q": "Moist O2 inhalation in bronchiolitis aims to keep SpO2 above ___.", "opts": ["92%", "85%", "99%", "80%"], "ans": 0, "exp": "Moist O2 inhalation (goal: SpO2 > 92%) (Book p125)", "type": "fill"},
 {"id": "PEDS-C28-073", "sec": "Bronchiolitis — management", "page": 125, "q": "Antivirals are used routinely in all cases of bronchiolitis.", "opts": ["True", "False"], "ans": 1, "exp": "False — antivirals not routinely used (Book p125)", "type": "tf"},
 {"id": "PEDS-C28-074", "sec": "Bronchiolitis — management", "page": 125, "q": "Inhaled ribavirin (nebulization) is reserved for —", "opts": ["Children > 5 yrs", "Mild self-limiting cases", "At-risk infants (chronic lung disease, CHD)", "All term neonates"], "ans": 2, "exp": "Used in at-risk infants: chronic lung disease, CHD (Book p125)", "type": "mcq"},
 {"id": "PEDS-C28-075", "sec": "Bronchiolitis — prevention", "page": 125, "q": "___ is a monoclonal antibody against RSV proteins used for prevention in at-risk infants.", "opts": ["Ribavirin", "Omalizumab", "Infliximab", "Palivizumab"], "ans": 3, "exp": "Palivizumab: monoclonal antibody against RSV proteins (Book p125)", "type": "fill"},
 {"id": "PEDS-C28-076", "sec": "Bronchiolitis — drugs", "page": 125, "q": "Odd one out (bronchiolitis-related agents):", "opts": ["Oral dexamethasone", "Palivizumab", "Inhaled ribavirin", "Moist O2"], "ans": 0, "exp": "Palivizumab (prevention), ribavirin (at-risk) and O2 (supportive) relate to bronchiolitis; dexamethasone is croup therapy. (Book p125)", "type": "odd"},
 {"id": "PEDS-C28-077", "sec": "Bronchiolitis — associations", "page": 125, "q": "Match item with role — select the correct combination:", "pairs": [["Palivizumab", "treatment in at-risk"], ["Ribavirin", "X-ray"], ["PCR swab", "prevention"], ["Hyperinflation", "diagnosis"]], "opts": ["A-2, B-1, C-4, D-3", "A-2, B-1, C-3, D-4", "A-3, B-1, C-4, D-2", "A-3, B-4, C-2, D-1"], "ans": 2, "exp": "Correct pairs: Palivizumab→prevention; Ribavirin→treatment in at-risk; PCR swab→diagnosis; Hyperinflation→X-ray. (Book p125)", "type": "match"},
 {"id": "PEDS-C28-078", "sec": "Bronchiolitis — case", "page": 125, "stem": "A 5-month-old in winter has wheeze, hyper-resonant chest and bilateral hyperinflation on X-ray.", "q": "The most appropriate management is —", "opts": ["IV ampicillin + gentamicin", "Immediate tracheostomy", "Supportive care with moist O2 (goal SpO2 > 92%) and fluids", "Routine oral antivirals for all"], "ans": 2, "exp": "Bronchiolitis is self-limiting; supportive — moist O2 + fluids. (Book p125)", "type": "case"},
 {"id": "PEDS-C28-079", "sec": "Pneumonia — definition", "page": 126, "q": "Pneumonia is an infection of the lung ___.", "opts": ["pleura", "pulmonary artery", "chest wall", "tissue / parenchyma"], "ans": 3, "exp": "Infection of lung tissue/parenchyma (Book p126)", "type": "fill"},
 {"id": "PEDS-C28-080", "sec": "Pneumonia — definition", "page": 126, "q": "Pneumonia is a leading cause of under-5 mortality.", "opts": ["True", "False"], "ans": 0, "exp": "True — leading cause of under 5 mortality (Book p126)", "type": "tf"},
 {"id": "PEDS-C28-081", "sec": "Pneumonia — etiology", "page": 126, "q": "The overall most common bacterial cause of pneumonia in children is —", "opts": ["Staphylococcus aureus", "Streptococcus pneumoniae", "E. coli", "Group-B streptococci"], "ans": 1, "exp": "Streptococcus pneumoniae (overall m/c) (Book p126)", "type": "mcq"},
 {"id": "PEDS-C28-082", "sec": "Pneumonia — etiology", "page": 126, "q": "The most common bacterial causes of pneumonia in NEONATES are —", "opts": ["Mycoplasma and Chlamydia", "Klebsiella and Pseudomonas", "E. coli and group-B streptococci", "Strep pneumoniae and RSV"], "ans": 2, "exp": "E. coli, group-B streptococci (m/c in neonates) (Book p126)", "type": "mcq"},
 {"id": "PEDS-C28-083", "sec": "Pneumonia — etiology", "page": 126, "q": "The most common viral cause of pneumonia is —", "opts": ["Parainfluenza", "Adenovirus", "Influenza A", "RSV"], "ans": 3, "exp": "Viral: RSV (m/c) (Book p126)", "type": "mcq"},
 {"id": "PEDS-C28-084", "sec": "Pneumonia — etiology", "page": 126, "q": "Because etiological diagnosis is not always feasible, X-ray findings are more reliable in pneumonia.", "opts": ["True", "False"], "ans": 0, "exp": "True — X-ray findings more reliable (Book p126)", "type": "tf"},
 {"id": "PEDS-C28-085", "sec": "Pneumonia — features", "page": 126, "q": "A productive wet cough in pneumonia may not be expectorated because —", "opts": ["Sputum is too viscous to form", "The child swallows the sputum", "The cough is purely dry", "Airway is fully obstructed"], "ans": 1, "exp": "Productive wet cough may not be expectorated (d/t swallowing) (Book p126)", "type": "mcq"},
 {"id": "PEDS-C28-086", "sec": "Pneumonia — features", "page": 126, "q": "Auscultation in pneumonia typically reveals —", "opts": ["Absent breath sounds always", "Pleural rub only", "Crepitations", "Wheeze only"], "ans": 2, "exp": "Crepitations on auscultation (Book p126)", "type": "mcq"},
 {"id": "PEDS-C28-087", "sec": "Pneumonia — features", "page": 126, "q": "Odd one out (pneumonia clinical features):", "opts": ["Fever", "Tachypnea", "Crepitations", "Hyper-resonance on percussion"], "ans": 3, "exp": "Fever, tachypnea and crepitations are pneumonia features; hyper-resonance suggests air-trapping (bronchiolitis). (Book p126)", "type": "odd"},
 {"id": "PEDS-C28-088", "sec": "IMNCI", "page": 126, "q": "The community pneumonia guidelines are given by ___ (IMNCI).", "opts": ["Integrated Management of Neonatal & Childhood Illness", "International Maternal & Neonatal Care Initiative", "Indian Module for Neonatal & Child Immunization", "Integrated Management of Nutrition & Childhood Infection"], "ans": 0, "exp": "Integrated Management of Neonatal & Childhood Illness (IMNCI) (Book p126)", "type": "fill"},
 {"id": "PEDS-C28-089", "sec": "IMNCI", "page": 126, "q": "IMNCI guidelines address management of pneumonia at —", "opts": ["Home without any classification", "Peripheral health setting / community level", "Only tertiary ICU", "Only private hospitals"], "ans": 1, "exp": "Management in a peripheral health setting / at community level (Book p126)", "type": "mcq"},
 {"id": "PEDS-C28-090", "sec": "IMNCI", "page": 126, "q": "A child with only fever and cough/cold (no fast breathing) is classified as —", "opts": ["Severe pneumonia", "Very severe disease", "No pneumonia", "Pneumonia"], "ans": 2, "exp": "No pneumonia: fever, cough/cold (Book p126)", "type": "mcq"},
 {"id": "PEDS-C28-091", "sec": "IMNCI", "page": 126, "q": "The 'pneumonia' category requires fast breathing and/or chest indrawing with —", "opts": ["SpO2 < 90%", "Cyanosis", "Convulsions", "Normal SpO2"], "ans": 3, "exp": "Pneumonia: fast breathing and/or chest indrawing; SpO2 normal (Book p126)", "type": "mcq"},
 {"id": "PEDS-C28-092", "sec": "IMNCI", "page": 126, "q": "Home management of the 'pneumonia' category is paracetamol plus oral ___ for 5 days.", "opts": ["amoxicillin", "azithromycin", "gentamicin", "cloxacillin"], "ans": 0, "exp": "PCT + oral amoxicillin × 5 d (Book p126)", "type": "fill"},
 {"id": "PEDS-C28-093", "sec": "IMNCI", "page": 126, "q": "If wheeze is present in the pneumonia category, add ___ for 5 days.", "opts": ["ceftriaxone", "salbutamol", "dexamethasone", "ribavirin"], "ans": 1, "exp": "If wheeze +: salbutamol × 5 d (Book p126)", "type": "fill"},
 {"id": "PEDS-C28-094", "sec": "IMNCI", "page": 126, "q": "A cough lasting more than ___ weeks should be evaluated for tuberculosis.", "opts": ["4", "8", "2", "1"], "ans": 2, "exp": "If cough > 2 wk: evaluate for tuberculosis (Book p126)", "type": "fill"},
 {"id": "PEDS-C28-095", "sec": "IMNCI", "page": 126, "q": "Severe pneumonia is defined by SpO2 < 90% OR —", "opts": ["Fever > 3 days", "Wheeze", "Cough > 1 week", "≥ 1 danger sign"], "ans": 3, "exp": "SpO2 < 90% OR ≥ 1 danger sign (Book p126)", "type": "mcq"},
 {"id": "PEDS-C28-096", "sec": "IMNCI", "page": 126, "q": "Odd one out (danger signs of severe pneumonia):", "opts": ["Fever", "Lethargy", "Not feeding", "Convulsions"], "ans": 0, "exp": "Danger signs: lethargy, not feeding, convulsions, cyanosis; fever alone is not a danger sign. (Book p126)", "type": "odd"},
 {"id": "PEDS-C28-097", "sec": "IMNCI", "page": 126, "q": "Danger signs of severe pneumonia include lethargy, not feeding, convulsions and ___.", "opts": ["headache", "cyanosis", "rhinorrhea", "otitis"], "ans": 1, "exp": "Cyanosis is a danger sign (Book p126)", "type": "fill"},
 {"id": "PEDS-C28-098", "sec": "IMNCI", "page": 126, "q": "The first dose given before/during referral of severe pneumonia is —", "opts": ["Inhaled salbutamol", "Oral paracetamol only", "IV ampicillin + gentamicin", "Oral amoxicillin"], "ans": 2, "exp": "1st dose: IV antibiotic (ampicillin + gentamicin) (Book p126)", "type": "mcq"},
 {"id": "PEDS-C28-099", "sec": "IMNCI", "page": 126, "q": "Match IMNCI category with management — select the correct combination:", "pairs": [["No pneumonia", "referral + IV amp+gent"], ["Pneumonia", "TB evaluate"], ["Severe pneumonia", "home PCT"], ["Cough > 2 wk", "amoxicillin ×5 d"]], "opts": ["A-3, B-2, C-1, D-4", "A-3, B-4, C-1, D-2", "A-2, B-3, C-1, D-4", "A-2, B-4, C-1, D-3"], "ans": 1, "exp": "Correct pairs: No pneumonia→home PCT; Pneumonia→amoxicillin ×5 d; Severe pneumonia→referral + IV amp+gent; Cough > 2 wk→TB evaluate. (Book p126)", "type": "match"},
 {"id": "PEDS-C28-100", "sec": "Fast breathing", "page": 127, "q": "Fast-breathing threshold for age < 2 months is RR > ___.", "opts": ["60/min", "50/min", "40/min", "70/min"], "ans": 0, "exp": "< 2 months: > 60/min (Book p127)", "type": "fill"},
 {"id": "PEDS-C28-101", "sec": "Fast breathing", "page": 127, "q": "Fast-breathing threshold for age 2–12 months is RR > ___.", "opts": ["60/min", "50/min", "40/min", "30/min"], "ans": 1, "exp": "2–12 months: > 50/min (Book p127)", "type": "fill"},
 {"id": "PEDS-C28-102", "sec": "Fast breathing", "page": 127, "q": "Fast-breathing threshold for age > 12 months is RR > ___.", "opts": ["30/min", "50/min", "40/min", "60/min"], "ans": 2, "exp": "> 12 months: > 40/min (Book p127)", "type": "fill"},
 {"id": "PEDS-C28-103", "sec": "Fast breathing", "page": 127, "q": "For a 14-month-old, a respiratory rate above 50/min defines fast breathing.", "opts": ["True", "False"], "ans": 1, "exp": "False — > 12 months threshold is > 40/min (Book p127)", "type": "tf"},
 {"id": "PEDS-C28-104", "sec": "IMNCI", "page": 127, "stem": "An 8-month-old has fever, cough, RR 55/min and chest indrawing; SpO2 96%.", "q": "IMNCI category and management —", "opts": ["Pneumonia → home PCT + oral amoxicillin ×5 d", "Severe pneumonia → urgent referral", "No pneumonia → paracetamol only", "Pneumonia → IV vancomycin"], "ans": 0, "exp": "Fast breathing (55 > 50 for 2–12 m) + chest indrawing + normal SpO2 = pneumonia → home oral amoxicillin. (Book p126–127)", "type": "case"},
 {"id": "PEDS-C28-105", "sec": "IMNCI", "page": 127, "stem": "A 10-month-old with pneumonia becomes cyanotic with SpO2 88%.", "q": "The correct next step is —", "opts": ["Observe for another 5 days", "Urgent referral to tertiary care + 1st dose IV ampicillin + gentamicin", "Continue home amoxicillin", "Add oral salbutamol only"], "ans": 1, "exp": "SpO2 < 90% + danger sign = severe pneumonia → urgent referral + IV 1st dose. (Book p126)", "type": "case"},
 {"id": "PEDS-C28-106", "sec": "Pneumococcal", "page": 127, "q": "Pneumococcal pneumonia is transmitted by ___.", "opts": ["blood", "vector", "droplet", "fecal–oral"], "ans": 2, "exp": "Mode of transmission: droplet (Book p127)", "type": "fill"},
 {"id": "PEDS-C28-107", "sec": "Pneumococcal", "page": 127, "q": "Pneumococcal pneumonia incidence rises in ___.", "opts": ["summer", "autumn", "spring", "winter"], "ans": 3, "exp": "Season of ↑ incidence: winter (Book p127)", "type": "fill"},
 {"id": "PEDS-C28-108", "sec": "Pneumococcal", "page": 127, "q": "The characteristic chest X-ray finding in pneumococcal pneumonia is ___ consolidation.", "opts": ["lobar", "interstitial", "patchy bilateral", "miliary"], "ans": 0, "exp": "Lobar consolidation on chest X-ray (Book p127)", "type": "fill"},
 {"id": "PEDS-C28-109", "sec": "Pneumococcal", "page": 127, "q": "If expectorated, the sputum of pneumococcal pneumonia is —", "opts": ["Clear watery", "Rusty", "Frothy pink", "Purulent green"], "ans": 1, "exp": "Sputum (if expectorated): rusty (Book p127)", "type": "mcq"},
 {"id": "PEDS-C28-110", "sec": "Pneumococcal", "page": 127, "q": "Percussion over a pneumococcal consolidation yields —", "opts": ["Resonant note", "Tympanic note", "Dull / impaired note", "Hyper-resonant note"], "ans": 2, "exp": "Dull/impaired note on percussion (Book p127)", "type": "mcq"},
 {"id": "PEDS-C28-111", "sec": "Pneumococcal", "page": 127, "q": "Auscultation over pneumococcal consolidation classically hears —", "opts": ["Absent sounds", "Wheeze", "Pleural friction only", "Bronchial breath sounds"], "ans": 3, "exp": "Bronchial sounds (Book p127)", "type": "mcq"},
 {"id": "PEDS-C28-112", "sec": "Pneumococcal", "page": 127, "q": "Penicillin G dose for pneumococcal pneumonia is ___ IU/kg/day IV for 5–7 days.", "opts": ["50,000", "10,000", "1,00,000", "5,000"], "ans": 0, "exp": "Penicillin G: 50,000 IU/kg/day IV for 5–7 days (Book p127)", "type": "fill"},
 {"id": "PEDS-C28-113", "sec": "Pneumococcal", "page": 127, "q": "If penicillin G is not available, the alternative is —", "opts": ["Oral azithromycin", "3rd-generation cephalosporins (IV ceftriaxone/cefotaxime)", "Oral amoxicillin", "Inhaled ribavirin"], "ans": 1, "exp": "If not available → 3rd generation cephalosporins (IV ceftriaxone, IV cefotaxime) (Book p127)", "type": "mcq"},
 {"id": "PEDS-C28-114", "sec": "Pneumococcal", "page": 127, "q": "Bronchial breath sounds with a dull percussion note support lobar consolidation.", "opts": ["True", "False"], "ans": 0, "exp": "True — bronchial sounds + dull/impaired note with lobar consolidation (Book p127)", "type": "tf"},
 {"id": "PEDS-C28-115", "sec": "Pneumococcal", "page": 127, "stem": "In winter, a child presents with high fever, rusty sputum and lobar consolidation on X-ray.", "q": "The first-line treatment is —", "opts": ["Oral azithromycin", "Inhaled salbutamol", "Palivizumab", "Penicillin G 50,000 IU/kg/day IV"], "ans": 3, "exp": "Pneumococcal lobar pneumonia → Penicillin G IV 5–7 d. (Book p127)", "type": "case"},
 {"id": "PEDS-C28-116", "sec": "Staph pneumonia", "page": 127, "q": "Staphylococcal pneumonia is caused by —", "opts": ["Staphylococcus aureus", "Streptococcus pneumoniae", "E. coli", "Mycoplasma"], "ans": 0, "exp": "Bacteria: Staphylococcus aureus (Book p127)", "type": "mcq"},
 {"id": "PEDS-C28-117", "sec": "Staph pneumonia", "page": 127, "q": "Staphylococcal pneumonia can arise by spread from a skin focus of —", "opts": ["Vitiligo", "Pyoderma", "Tinea", "Scabies"], "ans": 1, "exp": "Spread from different focus: pyoderma (skin) (Book p127)", "type": "mcq"},
 {"id": "PEDS-C28-118", "sec": "Staph pneumonia", "page": 127, "q": "Staphylococcal pneumonia may occur secondary to viral infections such as —", "opts": ["Rotavirus", "Hepatitis A", "Measles and influenza", "RSV only in neonates"], "ans": 2, "exp": "Secondary to viral infection (measles, influenza etc.) (Book p127)", "type": "mcq"},
 {"id": "PEDS-C28-119", "sec": "Staph pneumonia", "page": 127, "q": "Recurrent pneumonia in ___ should raise suspicion of staphylococcal etiology.", "opts": ["asthma", "croup", "epiglottitis", "cystic fibrosis"], "ans": 3, "exp": "Cystic fibrosis (recurrent pneumonia) (Book p127)", "type": "fill"},
 {"id": "PEDS-C28-120", "sec": "Staph pneumonia", "page": 127, "q": "The pathognomonic staph X-ray lesion is the ___ — air-filled cystic spaces.", "opts": ["pneumatocele", "pneumothorax", "pneumomediastinum", "bleb"], "ans": 0, "exp": "Pneumatocele: air-filled cystic spaces (pathognomonic) (Book p127)", "type": "fill"},
 {"id": "PEDS-C28-121", "sec": "Staph pneumonia", "page": 127, "q": "Rupture of a pneumatocele leads to —", "opts": ["Consolidation", "Pneumothorax", "Empyema", "Pericarditis"], "ans": 1, "exp": "Rupture → pneumothorax (Book p127)", "type": "mcq"},
 {"id": "PEDS-C28-122", "sec": "Staph pneumonia", "page": 127, "q": "Empyema seen in a child < ___ yr is most commonly of staphylococcal etiology.", "opts": ["10", "1", "2", "5"], "ans": 2, "exp": "Empyema (if seen in child < 2 yr → m/c staphylococcal etiology) (Book p127)", "type": "fill"},
 {"id": "PEDS-C28-123", "sec": "Staph pneumonia", "page": 127, "q": "B/L patchy consolidation with pus in staph pneumonia can be complicated by —", "opts": ["Pneumatocele only", "Asthma", "Croup", "Empyema and purulent pericarditis"], "ans": 3, "exp": "B/L patchy consolidation (with pus) → empyema, purulent pericarditis (Book p127)", "type": "mcq"},
 {"id": "PEDS-C28-124", "sec": "Staph pneumonia", "page": 128, "q": "The antibiotic regimen for staphylococcal pneumonia is —", "opts": ["Co-amoxiclav OR ceftriaxone + cloxacillin ×7–10 d", "Oral azithromycin ×3 d", "Penicillin G single dose", "Inhaled ribavirin"], "ans": 0, "exp": "Co-amoxiclav OR ceftriaxone + cloxacillin, 7 to 10 days (Book p128)", "type": "mcq"},
 {"id": "PEDS-C28-125", "sec": "Staph pneumonia", "page": 128, "q": "Co-amoxiclav is amoxicillin combined with ___.", "opts": ["clindamycin", "clavulanic acid", "sulbactam", "tazobactam"], "ans": 1, "exp": "Co-amoxiclav (amoxicillin & clavulanic acid) (Book p128)", "type": "fill"},
 {"id": "PEDS-C28-126", "sec": "Staph pneumonia", "page": 128, "q": "If MRSA is suspected in staphylococcal pneumonia, add —", "opts": ["Gentamicin", "Azithromycin", "Vancomycin", "Amoxicillin"], "ans": 2, "exp": "Suspected MRSA → + vancomycin (Book p128)", "type": "mcq"},
 {"id": "PEDS-C28-127", "sec": "Staph pneumonia", "page": 128, "q": "The duration of staph pneumonia antibiotic therapy is ___ days.", "opts": ["3 to 5", "1 to 2", "21 to 28", "7 to 10"], "ans": 3, "exp": "7 to 10 days (Book p128)", "type": "fill"},
 {"id": "PEDS-C28-128", "sec": "Staph pneumonia", "page": 128, "q": "Odd one out (staph pneumonia X-ray/complications):", "opts": ["Steeple sign", "Pneumatocele", "Empyema", "Purulent pericarditis"], "ans": 0, "exp": "Pneumatocele, empyema and purulent pericarditis are staph features; steeple sign belongs to croup. (Book p127–128)", "type": "odd"},
 {"id": "PEDS-C28-129", "sec": "Staph pneumonia", "page": 128, "q": "Match feature with association — select the correct combination:", "pairs": [["Pneumatocele", "skin focus"], ["Empyema in child < 2 yr", "rupture→pneumothorax"], ["Suspected MRSA", "m/c staph"], ["Pyoderma", "add vancomycin"]], "opts": ["A-2, B-4, C-1, D-3", "A-2, B-4, C-3, D-1", "A-4, B-1, C-2, D-3", "A-2, B-3, C-4, D-1"], "ans": 3, "exp": "Correct pairs: Pneumatocele→rupture→pneumothorax; Empyema in child < 2 yr→m/c staph; Suspected MRSA→add vancomycin; Pyoderma→skin focus. (Book p128)", "type": "match"},
 {"id": "PEDS-C28-130", "sec": "Staph pneumonia", "page": 128, "stem": "A child recovering from measles develops pneumonia with pneumatoceles on X-ray.", "q": "The likely organism and treatment are —", "opts": ["RSV → ribavirin", "Strep pneumoniae → penicillin only", "Staph aureus → co-amoxiclav OR ceftriaxone + cloxacillin", "Mycoplasma → azithromycin"], "ans": 2, "exp": "Post-measles + pneumatocele = staph → co-amoxiclav or ceftriaxone + cloxacillin. (Book p127–128)", "type": "case"},
 {"id": "PEDS-C28-131", "sec": "Atypical pneumonia", "page": 128, "q": "The most common organism causing primary atypical pneumonia is ___.", "opts": ["Strep pneumoniae", "E. coli", "RSV", "Mycoplasma"], "ans": 3, "exp": "Organisms: m/c mycoplasma (Book p128)", "type": "fill"},
