 {"id": "PEDS-C28-134", "sec": "Atypical pneumonia", "page": 128, "q": "In atypical pneumonia, X-ray findings are more significant than clinical findings.", "opts": ["True", "False"], "ans": 0, "exp": "True — X-ray findings more significant than clinical findings (Book p128)", "type": "tf"},
 {"id": "PEDS-C28-135", "sec": "Atypical pneumonia", "page": 128, "q": "The positive cold agglutination test reflects ___ against RBCs causing hemolysis.", "opts": ["IgG", "IgA", "IgE", "IgM"], "ans": 3, "exp": "IgM against RBC → hemolysis (Book p128)", "type": "fill"},
