 {"id": "PEDS-C28-137", "sec": "Atypical pneumonia", "page": 128, "q": "The X-ray pattern of atypical pneumonia is ___ pneumonia.", "opts": ["miliary", "interstitial", "lobar", "cavitating"], "ans": 1, "exp": "Interstitial pneumonia (Book p128)", "type": "fill"},
 {"id": "PEDS-C28-138", "sec": "Atypical pneumonia", "page": 128, "q": "Primary atypical pneumonia is commonly seen in children under 5 years.", "opts": ["True", "False"], "ans": 1, "exp": "False — age > 5 yr; rarely seen < 5 yr (Book p128)", "type": "tf"},
